import sqlite3
from datetime import datetime, timedelta

_DEFAULT_DB = "calendar.db"


def reschedule_calendar_event(event_id: int, new_start: str, duration_minutes: int = None, db_path: str = _DEFAULT_DB) -> dict:
    if not isinstance(event_id, int) or event_id <= 0:
        return {"ok": False, "error": "event_id must be a positive integer"}
    try:
        start_dt = datetime.fromisoformat(new_start)
    except (TypeError, ValueError):
        return {"ok": False, "error": "new_start must be an ISO 8601 datetime"}
    if duration_minutes is not None and (not isinstance(duration_minutes, int) or duration_minutes <= 0):
        return {"ok": False, "error": "duration_minutes must be a positive integer"}

    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT id, calendar_id, start_time, end_time FROM events WHERE id = ?",
            (event_id,),
        ).fetchone()
        if row is None:
            return {"ok": False, "error": f"event {event_id} not found"}

        if duration_minutes is None:
            old_start = datetime.fromisoformat(row["start_time"])
            old_end = datetime.fromisoformat(row["end_time"])
            delta = old_end - old_start
        else:
            delta = timedelta(minutes=duration_minutes)
        end_dt = start_dt + delta

        clash = conn.execute(
            "SELECT id, title FROM events WHERE calendar_id = ? AND id != ? "
            "AND start_time < ? AND end_time > ?",
            (row["calendar_id"], event_id, end_dt.isoformat(), start_dt.isoformat()),
        ).fetchone()
        if clash is not None:
            return {"ok": False, "error": f"conflicts with event {clash['id']} ({clash['title']})"}

        conn.execute(
            "UPDATE events SET start_time = ?, end_time = ?, updated_at = ? WHERE id = ?",
            (start_dt.isoformat(), end_dt.isoformat(), datetime.utcnow().isoformat(), event_id),
        )
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "event_id": event_id, "start": start_dt.isoformat(), "end": end_dt.isoformat()}

import sqlite3
from datetime import datetime, timedelta
from langchain_core.tools import tool


@tool
def book_first_free_slot(calendar_id: str, day: str, title: str, minutes: int) -> str:
    if not calendar_id or not title or minutes <= 0:
        return "Invalid calendar_id, title or minutes."
    try:
        d = datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        return "day must be YYYY-MM-DD."
    conn = sqlite3.connect("calendar.db")
    cursor = d.replace(hour=9)
    limit = d.replace(hour=17)
    rows = conn.execute("SELECT start_time, end_time FROM events WHERE calendar_id=? AND date(start_time)=? ORDER BY start_time", (calendar_id, day)).fetchall()
    for s, e in rows:
        if datetime.fromisoformat(s) - cursor >= timedelta(minutes=minutes):
            break
        cursor = max(cursor, datetime.fromisoformat(e))
    if cursor + timedelta(minutes=minutes) > limit:
        conn.close()
        return "No free slot available."
    end = cursor + timedelta(minutes=minutes)
    conn.execute("INSERT INTO events (calendar_id, title, start_time, end_time) VALUES (?,?,?,?)", (calendar_id, title, cursor.isoformat(), end.isoformat()))
    conn.commit()
    conn.close()
    return f"Booked {title} from {cursor.isoformat()} to {end.isoformat()}."
